let RU=0;
function regVec(X,Y,land,box,sx){const id='lc'+(++RU),pt=a=>X(a[0])+' '+Y(a[1]),bl=Math.max(3,Math.min(9,sx*.12)).toFixed(1);let p='',t='';
 REGIONS.forEach(r=>{p+=`<path d="M${r[2].map(pt).join('L')}Z" fill="${r[1]}"/>`;const c=r[3];if(c[0]>box[0]&&c[0]<box[1]&&c[1]>box[2]&&c[1]<box[3]){const xs=r[2].map(a=>a[0]),wpx=(Math.max(...xs)-Math.min(...xs))*(X(1)-X(0)),fs=Math.max(8.5,Math.min(17,wpx/(r[0].length*1.05)));t+=`<text class="jrg" style="font-size:${fs.toFixed(1)}px" x="${X(c[0])}" y="${Y(c[1])}" text-anchor="middle">${esc(r[0])}</text>`}});
 return `<defs><clipPath id="${id}"><path d="${land}" clip-rule="evenodd"/></clipPath><filter id="${id}b" x="-10%" y="-10%" width="120%" height="120%"><feGaussianBlur stdDeviation="${bl}"/></filter></defs><g clip-path="url(#${id})"><g class="jfl" filter="url(#${id}b)">${p}</g><g class="jbd" fill="none" stroke="#fff" stroke-opacity=".35" stroke-width="1">${p.replace(/ fill="[^"]*"/g,'')}</g></g>${t}`}

// ---- gap-free territories: every pixel goes to the nearest territory, borders smoothed, neighbours never share a colour ----
const PAL=['#F0B9A8','#E9D98E','#A9C9A0','#B8A9CF','#9CB9C9','#F2C58E','#D9A6B8','#C8D3A0'];
function partition(polys,w,h,lm){
 const n=polys.length,N=w*h,D={},act=[];
 polys.forEach((p,i)=>{let x0=1e9,x1=-1e9,y0=1e9,y1=-1e9;p.forEach(a=>{x0=Math.min(x0,a[0]);x1=Math.max(x1,a[0]);y0=Math.min(y0,a[1]);y1=Math.max(y1,a[1])});if(x1<-200||x0>w+200||y1<-200||y0>h+200)return;act.push(i)});
 const bl=(a,r)=>{const t=new Float32Array(N),o=new Float32Array(N),q=2*r+1,cl=(v,m)=>v<0?0:v>m?m:v;
  for(let y=0;y<h;y++){let s=0;for(let k=-r;k<=r;k++)s+=a[y*w+cl(k,w-1)];t[y*w]=s/q;for(let x=1;x<w;x++){s+=a[y*w+cl(x+r,w-1)]-a[y*w+cl(x-r-1,w-1)];t[y*w+x]=s/q}}
  for(let x=0;x<w;x++){let s=0;for(let k=-r;k<=r;k++)s+=t[cl(k,h-1)*w+x];o[x]=s/q;for(let y=1;y<h;y++){s+=t[cl(y+r,h-1)*w+x]-t[cl(y-r-1,h-1)*w+x];o[y*w+x]=s/q}}
  return o};
 act.forEach(i=>{const p=polys[i],m=p.length,d=new Float32Array(N);
  for(let y=0;y<h;y++)for(let x=0;x<w;x++){let ins=false,md=1e18;
   for(let a=0,b=m-1;a<m;b=a++){const ax=p[a][0],ay=p[a][1],bx=p[b][0],by=p[b][1];if((ay>y)!==(by>y)&&x<(bx-ax)*(y-ay)/(by-ay)+ax)ins=!ins;
    const dx=bx-ax,dy=by-ay,t=Math.max(0,Math.min(1,((x-ax)*dx+(y-ay)*dy)/(dx*dx+dy*dy||1))),ex=ax+t*dx-x,ey=ay+t*dy-y,dd=ex*ex+ey*ey;if(dd<md)md=dd}
   d[y*w+x]=ins?-6-i*.02:Math.sqrt(md)}
  D[i]=bl(bl(d,3),3)});
 const lab=new Int16Array(N);
 for(let k=0;k<N;k++){let bi=-1,bv=1e18;for(let j=0;j<act.length;j++){const v=D[act[j]][k];if(v<bv){bv=v;bi=act[j]}}lab[k]=bi}
 const nb={};const link=(a,b)=>{if(a===b)return;(nb[a]=nb[a]||new Set()).add(b);(nb[b]=nb[b]||new Set()).add(a)};
 for(let y=0;y<h-1;y++)for(let x=0;x<w-1;x++){const k=y*w+x;if(lm&&!lm[k])continue;link(lab[k],lab[k+1]);link(lab[k],lab[k+w])}
 const col={},ord=act.slice().sort((a,b)=>(nb[b]?nb[b].size:0)-(nb[a]?nb[a].size:0));
 ord.forEach(i=>{const used=new Set();(nb[i]||[]).forEach(j=>{if(col[j]!==undefined)used.add(col[j])});let c=0;while(used.has(c)&&c<PAL.length)c++;col[i]=c%PAL.length});
 return {lab,col,act}}

const RC={};
function regRaster(X,Y,land,W,H){
 const sc=.6,w=Math.ceil(W*sc),h=Math.ceil(H*sc),cv=document.createElement('canvas');cv.width=w;cv.height=h;const g=cv.getContext('2d');
 g.scale(sc,sc);g.fill(new Path2D(land),'evenodd');
 const ld=g.getImageData(0,0,w,h).data,lm=new Uint8Array(w*h);for(let i=0;i<lm.length;i++)lm[i]=ld[i*4+3]>100?1:0;
 const P=partition(REGIONS.map(r=>r[2].map(a=>[X(a[0])*sc,Y(a[1])*sc])),w,h,lm),lab=P.lab,rgb=PAL.map(c=>[1,3,5].map(i=>parseInt(c.substr(i,2),16)));
 g.setTransform(1,0,0,1,0,0);g.clearRect(0,0,w,h);
 const im=g.createImageData(w,h),bm=g.createImageData(w,h),st={};
 for(let y=0;y<h;y++)for(let x=0;x<w;x++){const k=y*w+x,i=lab[k],c=rgb[P.col[i]];im.data[k*4]=c[0];im.data[k*4+1]=c[1];im.data[k*4+2]=c[2];im.data[k*4+3]=255;
  if(lm[k]){const o=st[i]=st[i]||{n:0,sx:0,sy:0,x0:1e9,x1:-1};o.n++;o.sx+=x;o.sy+=y;o.x0=Math.min(o.x0,x);o.x1=Math.max(o.x1,x)}
  if((x+1<w&&lab[k+1]!==i&&(lm[k]||lm[k+1]))||(y+1<h&&lab[k+w]!==i&&(lm[k]||lm[k+w]))){bm.data[k*4]=bm.data[k*4+1]=bm.data[k*4+2]=255;bm.data[k*4+3]=230}}
 g.putImageData(im,0,0);const f=cv.toDataURL('image/png');g.clearRect(0,0,w,h);g.putImageData(bm,0,0);const b=cv.toDataURL('image/png');
 let t='';Object.keys(st).forEach(i=>{const o=st[i];if(o.n<220)return;const nm=REGIONS[i][0],fs=Math.max(8.5,Math.min(17,(o.x1-o.x0)/sc/(nm.length*1.0)));t+=`<text class="jrg" style="font-size:${fs.toFixed(1)}px" x="${(o.sx/o.n/sc).toFixed(1)}" y="${(o.sy/o.n/sc).toFixed(1)}" text-anchor="middle">${esc(nm)}</text>`});
 return {f,b,t}}
function regSVG(X,Y,land,box,sx,W,H){
 try{if(typeof document==='undefined'||!document.createElement||typeof Path2D==='undefined')throw 0;
  const key=box+'|'+W+'|'+H;const R=RC[key]||(RC[key]=regRaster(X,Y,land,W,H)),id='lc'+(++RU);
  return `<defs><clipPath id="${id}"><path d="${land}" clip-rule="evenodd"/></clipPath></defs><g clip-path="url(#${id})"><image class="jfimg" href="${R.f}" x="0" y="0" width="${W}" height="${H}" preserveAspectRatio="none"/><image class="jbdimg" href="${R.b}" x="0" y="0" width="${W}" height="${H}" preserveAspectRatio="none"/></g>${R.t}`}
 catch(e){return regVec(X,Y,land,box,sx)}}
function compass(w,h,sx,k){const x=w-34,y=h-44,km=[50,100,200,500,1000].find(v=>v*sx*k/111>=60)||1000,L=km*sx*k/111;
 return `<g transform="translate(${x} ${y})"><path d="M0-17L5 0L0-4L-5 0Z" fill="#6b4f3a"/><path d="M0 17L5 0L0 4L-5 0Z" fill="#fff" stroke="#6b4f3a" stroke-width=".8"/><text y="-21" text-anchor="middle" class="jn2">N</text></g><g transform="translate(${w-30-L} ${h-12})"><path d="M0-4V0H${L.toFixed(0)}V-4" fill="none" stroke="#5a4636" stroke-width="1.2"/><text x="${(L/2).toFixed(0)}" y="-6" text-anchor="middle" class="jn2">${km} km</text></g>`}

